// 投稿生成結果を確認し、次のステップへ渡すデータを整形
const response = $input.first().json;

if (!response || !response.ok) {
  throw new Error('投稿生成に失敗しました: ' + JSON.stringify(response?.error || '不明なエラー'));
}

const post = response.post || {};
const tweetText = [
  post.post || '',
  '',
  (post.hashtags || []).join(' '),
  post.link || ''
].join('\n').trim();

return [{
  json: {
    tweetText: tweetText,
    tweetId: response.tweetId || null,
    affiliateLink: post.link || '',
    staffName: 'すなくん',
    generatedAt: new Date().toISOString()
  }
}];
